-- S1 · parte 3: artículos
create function pg_temp.med(u text) returns uuid language sql as $$ select id from public.medios where url_origen = u order by creado_en limit 1 $$;
create function pg_temp.gal(urls text[]) returns jsonb language sql as $$ select coalesce(jsonb_agg(jsonb_build_object('medio', pg_temp.med(u), 'pie', '') order by o), '[]'::jsonb) from unnest(urls) with ordinality t(u, o) $$;
insert into public.articulos (id_antiguo, slug, titulo, fecha, extracto, contenido, categoria_id, imagen_id, estado, publicado_en)
values ('el-arte-de-contar-historias-con-luz', 'el-arte-de-contar-historias-con-luz', 'Dirección de fotografía: el arte de contar historias con luz', '2024-07-15', 'Cómo pienso la luz cuando cuento una historia, con ejemplos de mis propios rodajes.', $t${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuando empiezo un proyecto, lo primero que me pregunto no es qué cámara voy a usar. Me pregunto qué quiero que sienta quien mira. La luz es la forma más directa que tengo de decidirlo: un cambio pequeño en su dirección o en su calidad puede convertir un espacio acogedor en uno amenazante, o a un personaje en alguien en quien confiar o de quien desconfiar."}]},{"type":"paragraph","content":[{"type":"text","text":"Me obsesiona la luz natural. Me fijo en cómo cae a distintas horas, en la suavidad de la hora mágica, en cómo se cuela por una persiana. Pero no siempre se puede depender de ella, y ahí empieza el oficio: recrearla, o inventar otra, con difusores, reflectores y una posición muy cuidada."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando la luz sale de la mente"}]},{"type":"paragraph","content":[{"type":"text","text":"En "},{"type":"text","text":"El Cirujano","marks":[{"type":"italic"}]},{"type":"text","text":" quise que la luz no tuviera una fuente lógica. En las escenas del asesino no hay lámparas ni ventanas que lo justifiquen: la luz sale de su cabeza, y por eso es un rojo abrasador. Todo lo demás, la investigación, es frío y analítico. Ese choque es la historia."}]},{"type":"paragraph","content":[{"type":"text","text":"!"},{"type":"text","text":"Escena de El Cirujano con la luz roja del asesino","marks":[{"type":"link","attrs":{"href":"https://www.platinocrowdfunding.com/storage/project/5454/img/bj9n3eW3a65uyo5krgOrW1dhpgJAtqk8bvY5x687.png \"El Cirujano. Premio a la mejor fotografía en On Duty International Film Festival.\""}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando el color cuenta el tiempo"}]},{"type":"paragraph","content":[{"type":"text","text":"En el EP "},{"type":"text","text":"Oscuridad","marks":[{"type":"italic"}]},{"type":"text","text":" usé el color como reloj. Empezamos la primera canción a todo color y, tema a tema, fuimos desaturando la imagen hasta acabar en blanco y negro. Nadie dice que la relación se está rompiendo; se ve."}]},{"type":"paragraph","content":[{"type":"text","text":"!"},{"type":"text","text":"Fotograma del EP Oscuridad de Adrián Muñoz","marks":[{"type":"link","attrs":{"href":"https://i.imgur.com/MgsvdAf.png \"EP Oscuridad, Adrián Muñoz.\""}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando la luz protege"}]},{"type":"paragraph","content":[{"type":"text","text":"En "},{"type":"text","text":"No se está tan mal","marks":[{"type":"italic"}]},{"type":"text","text":" la luz tenía que ser un refugio. En lugar de iluminar plano, esculpí el espacio con destellos, contraluces y reflejos en cristal y agua, para que el artista estuviera dentro de una burbuja donde pudiera mostrarse sin miedo."}]},{"type":"paragraph","content":[{"type":"text","text":"!"},{"type":"text","text":"Fotograma de No se está tan mal, de Lovva, con reflejos y contraluces","marks":[{"type":"link","attrs":{"href":"https://i.ibb.co/tPwcqPyC/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-00-44-400.jpg \"No se está tan mal, Lovva.\""}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando no tienes nada"}]},{"type":"paragraph","content":[{"type":"text","text":"En mis recreaciones aprendí lo que más me gusta del oficio. Para la ventana de Vito Corleone usé la rejilla de una estufa de butano, cinta negra y papel de horno. Con eso y una luz bien colocada, un sótano se convierte en un despacho de "},{"type":"text","text":"El Padrino","marks":[{"type":"italic"}]},{"type":"text","text":". La luz no necesita presupuesto; necesita intención."}]},{"type":"paragraph","content":[{"type":"text","text":"!"},{"type":"text","text":"Recreación del despacho de Vito Corleone de El Padrino","marks":[{"type":"link","attrs":{"href":"https://i.ibb.co/jP2769Q5/Captura-de-pantalla-2026-05-13-154204.png \"Recreación de El Padrino, rodada en un sótano.\""}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cada proyecto es un lienzo distinto, y la luz es siempre mi herramienta principal para contar la historia."}]}]}$t$::jsonb, (select id from public.categorias_articulo where nombre = 'Dirección de fotografía'), pg_temp.med('https://www.platinocrowdfunding.com/storage/project/5454/img/eO2uv54rRAQy1AgsNjm0ybjXLN92jg4mkW9zFxZR.png'), 'publicado', now())
on conflict (idioma, id_antiguo) do update set slug = excluded.slug, titulo = excluded.titulo, fecha = excluded.fecha, extracto = excluded.extracto, contenido = excluded.contenido, categoria_id = excluded.categoria_id, imagen_id = excluded.imagen_id;
insert into public.articulos (id_antiguo, slug, titulo, fecha, extracto, contenido, categoria_id, imagen_id, estado, publicado_en)
values ('ia-artesano-audiovisual', 'ia-artesano-audiovisual', 'El Artesano y la Inteligencia Artificial en el Cine', '2025-05-13', '¿Cómo afecta la IA a la producción audiovisual? Reflexiones sobre el futuro del cine y el trabajo artesano del videógrafo.', $t${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El mundo audiovisual ha sido, hasta ahora, un trabajo artesano. Pero ¿dónde queda nuestra huella cuando una IA puede imitar en segundos un estilo que tardamos años en construir?"}]},{"type":"paragraph","content":[{"type":"text","text":"Esa es la gran duda. En nuestro oficio, la mano, el gusto y la experiencia van puliendo una voz propia. Y aunque una inteligencia artificial pueda replicar una estética, difícilmente tendrá esa \"alma\" o esa riqueza de matices que surgen de la vivencia humana."}]},{"type":"paragraph","content":[{"type":"text","text":"Esta semana he estado dándole muchas vueltas y creo que merece la pena pararse a pensarlo."}]},{"type":"paragraph","content":[{"type":"text","text":"A muchos compañeros, e incluso a mí mismo, nos genera cierto rechazo ver obras generadas al 100 % por IA. A menudo se sienten vacías y, de alguna manera, invasoras. Sin embargo, creo que ese rechazo viene de mirar desde el ángulo equivocado, y de dejar de lado su verdadero potencial."}]},{"type":"paragraph","content":[{"type":"text","text":"La clave está en no ver a la IA como la \"creadora\". Hay que verla como el mejor asistente posible."}]},{"type":"paragraph","content":[{"type":"text","text":"!"},{"type":"text","text":"Maqueta en miniatura de la Ciudad Nube para la recreación de El Imperio Contraataca","marks":[{"type":"link","attrs":{"href":"https://i.imgur.com/wij6Im5.jpeg \"Una maqueta, siluetas y sables añadidos fotograma a fotograma: mi recreación de El Imperio Contraataca.\""}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Es una herramienta poderosísima para ejecutar ideas que antes eran imposibles sin presupuestos desorbitados. Y la clave está en integrarla en el flujo de trabajo para potenciarnos a nosotros, no para sustituirnos."}]},{"type":"paragraph","content":[{"type":"text","text":"Estamos viendo pasos gigantes en el buen camino. Me gusta mucho el enfoque de Runway: herramientas que buscan darnos control total sobre lo que hacemos, en lugar de dejarlo todo al azar. Su potencial, para mí, está en poder modificar el propio material que hemos grabado: incluir público en un estadio, añadir efectos visuales muy costosos o matizar la iluminación si en rodaje no ha quedado como esperábamos. Lo mismo con lo que se pudo ver la semana pasada en Adobe Max: la integración de la IA generativa directamente en nuestros timelines."}]},{"type":"paragraph","content":[{"type":"text","text":"En conclusión, creo que la tecnología cambia y avanza, pero somos nosotros quienes tenemos que construir el camino, haciendo un uso responsable e inteligente de ella. La inteligencia artificial no va a reemplazar al artesano, pero el artesano que sepa usar estas nuevas herramientas tendrá un taller mucho más potente para materializar su visión."}]}]}$t$::jsonb, (select id from public.categorias_articulo where nombre = 'Oficio'), pg_temp.med('https://i.ibb.co/KxmsqgfX/Captura-de-pantalla-2026-05-13-154839.png'), 'publicado', now())
on conflict (idioma, id_antiguo) do update set slug = excluded.slug, titulo = excluded.titulo, fecha = excluded.fecha, extracto = excluded.extracto, contenido = excluded.contenido, categoria_id = excluded.categoria_id, imagen_id = excluded.imagen_id;
